def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # The colored motif is a set of diagonal strokes. Extend each stroke
    # outward from its endpoint, preserving the endpoint's color.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 6:
                continue
            for dr, dc in ((1, 1), (-1, -1), (1, -1), (-1, 1)):
                r1, c1 = r + dr, c + dc
                if not (0 <= r1 < h and 0 <= c1 < w):
                    continue
                if grid[r1][c1] == color:
                    r2, c2 = r + 2 * dr, c + 2 * dc
                    while 0 <= r2 < h and 0 <= c2 < w and grid[r2][c2] == 6:
                        out[r2][c2] = color
                        r2 += dr
                        c2 += dc
    return out
